class LimitedLog {
    std::vector<int> entries_;
    std::size_t limit_;
public:
    explicit LimitedLog(std::size_t limit) : limit_(limit) {}
    bool try_append(int value) {
        if (entries_.size() == limit_) return false;
        entries_.push_back(value);
        return true;
    }
    std::size_t size() const { return entries_.size(); }
};

