struct Sender {
    virtual bool send(std::string_view text) = 0;
    virtual ~Sender() = default;
};
struct LegacyPrinter {
    bool emit(const char* data, std::size_t length) {
        for (std::size_t i = 0; i < length; ++i)
            std::cout << data[i];
        return true;
    }
};
class PrinterAdapter final : public Sender {
    LegacyPrinter& printer_;
public:
    explicit PrinterAdapter(LegacyPrinter& printer) : printer_(printer) {}
    bool send(std::string_view text) override {
        return printer_.emit(text.data(), text.size());
    }
};
int main() {
    LegacyPrinter printer;
    PrinterAdapter adapter{printer};
    Sender& sender = adapter;
    bool accepted = sender.send("Hi");
    std::cout << ' ' << accepted; // Hi 1
}

class LoggedSender final : public Sender {
    Sender& next_;
public:
    explicit LoggedSender(Sender& next) : next_(next) {}
    bool send(std::string_view text) override {
        std::cout << '[';
        bool accepted = next_.send(text);
        std::cout << ']';
        return accepted;
    }
};

class GateSender final : public Sender {
    Sender& next_;
    bool allowed_;
public:
    GateSender(Sender& next, bool allowed) : next_(next), allowed_(allowed) {}
    bool send(std::string_view text) override {
        if (!allowed_) return false;
        return next_.send(text);
    }
};

